# =====================================================================
#  events.map - phishing phrases for exhibitions, trade fairs,
#  conferences, event agencies and exhibitors
#  Part of: phywall by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : attendee / visitor / exhibitor list sale scams, fake
#           hosted buyer programs, fake housing bureaus and hotel
#           block "official" bookings, booth / stand / sponsorship
#           invoices with changed bank details, exhibitor directory
#           and catalogue listing scams, fake visa invitation letters,
#           fake speaker invitations, event platform account lures
#
#  Avoided: normal event mails ("your badge is ready", "agenda for
#           day 2", "thank you for visiting our stand"), because
#           event people send and receive them every day.
# =====================================================================

# ===== English =====
# Attendee list sales
/(attendee|attendees|visitor|visitors|delegate|participant|exhibitor|buyer)\s+(e-?mail\s+|contact\s+|data\s+|mailing\s+)?(list|database|data)\s+(of|for|from)[^.]{0,60}(is\s+)?(available|for\s+sale|ready)/i
/(would\s+you\s+be|are\s+you)\s+interested\s+in\s+(acquiring|purchasing|buying|getting)\s+(the\s+)?(attendee|attendees|visitor|visitors|exhibitor|delegate|participant|buyer)s?\s+(e-?mail\s+|contact\s+)?(list|database|data)/i
/(verified|updated|opt-?in)\s+(attendee|visitor|exhibitor|delegate|buyer)\s+(contacts?|list|database)[^.]{0,80}(counts?|pricing|cost|sample)/i
/(\d[\d,.]*)\s+(verified\s+)?(attendees|visitors|delegates|exhibitors|contacts)\s+(with\s+)?(complete\s+)?(contact\s+)?(details|information|info)[^.]{0,30}(available|interested|pricing)/i
# Hosted buyer programs
/(join|apply\s+for|register\s+for)\s+(the\s+)?[^.]{0,30}hosted\s+buyers?\s+(program|programme)/i
/(you\s+have\s+been|you\s+are)\s+(selected|invited|nominated|approved)\s+(as|for|to\s+join)\s+(a\s+|the\s+)?[^.]{0,30}(hosted\s+buyer|vip\s+buyer|top\s+buyer)/i
/(complimentary|free|fully\s+paid)\s+(flights?|accommodation|hotel|travel)[^.]{0,40}(hosted\s+buyer|buyer\s+program|qualified\s+buyers?)/i
/hosted\s+buyers?\s+(opportunity|invitation|application|nomination)/i
# Housing / hotel blocks
/(official\s+)?(housing\s+(bureau|provider|company)|accommodation\s+(provider|partner)|hotel\s+(block|booking)\s+(agent|partner))\s+(for|of)[^.]{0,50}(expo|exhibition|fair|conference|congress|summit|show|event)/i
/(secure|reserve|book|confirm)\s+(your\s+)?(hotel\s+)?(rooms?|accommodation)\s+(at\s+)?(the\s+)?(discounted|special|exhibitor|group|event)(\s+(exhibitor|group|event))?\s+rates?\s+(before|now|today)[^.]{0,30}(sold\s+out|limited|deadline)/i
/(rooms?|hotels?)\s+(near|close\s+to)\s+(the\s+)?(venue|exhibition\s+(center|centre)|fairground)\s+(are\s+)?(selling\s+out|almost\s+sold\s+out|limited)/i
# Booth / stand / sponsorship payments
/(booth|stand|space|sponsorship|exhibitor)\s+(fee|payment|invoice|balance)[^.]{0,40}(new|updated|changed)\s+(bank|banking|account)\s+(details|information)/i
/(your\s+)?(booth|stand|space)\s+(reservation|booking|allocation)\s+(will\s+be|has\s+been)\s+(cancelled|released|reassigned)\s+(unless|if\s+payment)/i
/(final|last)\s+(reminder|notice)[^.]{0,30}(booth|stand|exhibitor|sponsorship)\s+(payment|invoice|balance)/i
# Directory / catalogue scams
/(update|confirm|correct|verify)\s+your\s+(company\s+)?(listing|entry|details|profile)\s+(in|for)\s+(the\s+)?(official\s+)?(exhibitor|expo|fair|trade\s+show|official)\s+(directory|catalogue|catalog|guide|database)/i
/(exhibitor|expo|fair)\s+(directory|catalogue|catalog)[^.]{0,40}(free\s+of\s+charge|basic\s+entry|update\s+form)[^.]{0,40}(sign|return|complete)/i
# Visa / invitation letters
/(visa\s+)?invitation\s+letter\s+(for\s+(the\s+)?[^.]{0,40}(expo|exhibition|fair|conference|congress|summit|event)\s+)?(is\s+)?(ready|available|attached)[^.]{0,30}(download|view|pay|fee)/i
/(you\s+have\s+been|we\s+are\s+pleased\s+to)\s+(invited?|invite\s+you)\s+(as\s+a\s+|to\s+be\s+a\s+)?(speaker|panelist|keynote)[^.]{0,80}(registration|participation|speaker)\s+fee/i
# Event platforms
/(eventbrite|cvent|swapcard|hopin|bizzabo|whova|map\s*your\s*show|a2z|expocad)\s+(exhibitor\s+)?(portal\s+)?(account|profile|payouts?)\s+(has\s+been\s+|will\s+be\s+|is\s+)?(suspended|locked|restricted|on\s+hold|deactivated)/i
/(exhibitor|organizer|organiser)\s+(portal|account|manual)[^.]{0,30}(log\s*in|sign\s*in|verify|activate)\s+(now|today|before|within|to\s+(avoid|keep|access))/i

# ===== Spanish =====
/(lista|base\s+de\s+datos)\s+de\s+(asistentes|visitantes|expositores|compradores)\s+(de|del|para)[^.]{0,50}(disponible|a\s+la\s+venta)/iu
/(le\s+interesar[íi]a|est[áa]\s+interesad[oa]\s+en)\s+(adquirir|comprar|obtener)\s+(la\s+)?(lista|base\s+de\s+datos)\s+de\s+(asistentes|visitantes|expositores)/iu
/programa\s+(de\s+)?(compradores\s+invitados|hosted\s+buyers?)/iu
/(pago|factura)\s+del\s+(stand|espacio|patrocinio)[^.]{0,30}(nuevos?|cambio\s+de)\s+(datos\s+bancarios|cuenta)/iu

# ===== German =====
/(teilnehmer|besucher|aussteller|einkäufer|einkaeufer)[-\s]?(liste|datenbank|adressen)\s+(der|des|f[üu]r)[^.]{0,50}(verf[üu]gbar|zu\s+verkaufen|erh[äa]ltlich)/iu
/(h[äa]tten\s+sie|sind\s+sie)\s+interesse\s+(an\s+)?(der\s+)?(teilnehmer|besucher|aussteller)[-\s]?(liste|datenbank)/iu
/(standmiete|standgeb[üu]hr|ausstellergeb[üu]hr|sponsoring)[^.]{0,30}(neue|ge[äa]nderte)\s+(bankverbindung|kontodaten)/iu
/(ausstellerverzeichnis|messekatalog)[^.]{0,30}(eintrag|daten)\s+(aktualisieren|best[äa]tigen|pr[üu]fen)/iu

# ===== French =====
/(liste|base\s+de\s+donn[ée]es|fichier)\s+des\s+(participants|visiteurs|exposants|acheteurs)\s+(de|du|pour)[^.]{0,50}(disponible|en\s+vente)/iu
/(seriez-vous|[êe]tes-vous)\s+int[ée]ress[ée]\s+par\s+(l'acquisition\s+de\s+)?(la\s+)?(liste|base)\s+des\s+(participants|visiteurs|exposants)/iu
/(paiement|facture)\s+(du\s+)?(stand|espace|sponsoring)[^.]{0,30}(nouvelles?|changement\s+de)\s+(coordonn[ée]es\s+bancaires|rib)/iu
/(catalogue|annuaire)\s+des\s+exposants\s+[^.]{0,30}(mettre\s+[àa]\s+jour|confirmer|v[ée]rifier)/iu

# ===== Italian =====
/(lista|elenco|database)\s+(dei\s+)?(partecipanti|visitatori|espositori|buyer)\s+(di|del|della|per)[^.]{0,50}(disponibile|in\s+vendita)/iu
/(sarebbe|siete)\s+interessat[oi]\s+(ad\s+)?(acquistare|ricevere)\s+(la\s+)?(lista|database)\s+(dei\s+)?(partecipanti|visitatori|espositori)/iu
/(pagamento|fattura)\s+(dello\s+)?(stand|spazio\s+espositivo|sponsorizzazione)[^.]{0,30}(nuove|variazione)\s+(coordinate\s+bancarie|iban)/iu

# ===== Portuguese =====
/(lista|base\s+de\s+dados|banco\s+de\s+dados)\s+de\s+(participantes|visitantes|expositores|compradores)\s+(da|do|de|para)[^.]{0,50}(dispon[íi]vel|[àa]\s+venda)/iu
/(estaria|est[áa])\s+interessad[oa]\s+em\s+(adquirir|comprar)\s+(a\s+)?(lista|base)\s+de\s+(participantes|visitantes|expositores)/iu
/(pagamento|fatura)\s+do\s+(estande|stand|espa[çc]o|patroc[íi]nio)[^.]{0,30}(novos|altera[çc][ãa]o\s+de)\s+dados\s+banc[áa]rios/iu

