/(lista|baza)\s+(uczestnik[óo]w|odwiedzaj[ąa]cych|wystawc[óo]w)[^.]{0,50}(dost[ęe]pna|na\s+sprzeda[żz])/iu
/(op[łl]ata|faktura)\s+za\s+(stoisko|powierzchni[ęe]|sponsoring)[^.]{0,30}(nowe|zmiana)\s+(danych|numeru\s+konta)/iu

# ===== Turkish =====
/(kat[ıi]l[ıi]mc[ıi]|ziyaret[çc]i|kat[ıi]l[ıi]mc[ıi]lar|ziyaret[çc]iler|kat[ıi]l[ıi]mc[ıi]\s+firma|fuar\s+ziyaret[çc]i)\s+(listesi|veritaban[ıi]|data(s[ıi])?)[^.]{0,50}(mevcut|sat[ıi][şs]ta|ilginizi\s+[çc]eker)/iu
/(al[ıi]m\s+heyeti|hosted\s+buyer)\s+(program[ıi]na|program[ıi])\s+(kat[ıi]l[ıi]n|davet|se[çc]ildiniz)/iu
/(stand|alan|sponsorluk)\s+(bedeli|[öo]demesi|faturas[ıi])[^.]{0,30}(yeni|de[ğg]i[şs]en|g[üu]ncel)\s+(iban|banka\s+bilgileri|hesap)/iu
/(fuar|kat[ıi]l[ıi]mc[ıi])\s+katalo[ğg]u\s+[^.]{0,30}(bilgilerinizi\s+)?(g[üu]ncelleyin|onaylay[ıi]n)/iu

