/(i[şs]tirak[çc][ıi]|ziyar[əe]t[çc]i|s[əe]rgi\s+i[şs]tirak[çc][ıi]s[ıi])\s*(lar[ıi]n[ıi]n)?\s+(siyah[ıi]s[ıi]|bazas[ıi]|m[əe]lumat\s+bazas[ıi])[^.]{0,50}(m[öo]vcuddur|sat[ıi][şs]dad[ıi]r|maraql[ıi]d[ıi]r)/iu
/(stend|sah[əe]|sponsorluq)\s+(haqq[ıi]|[öo]d[əe]ni[şs]i|hesab-faktura)[^.]{0,30}(yeni|d[əe]yi[şs]dirilmi[şs])\s+(bank\s+rekvizitl[əe]ri|hesab|iban)/iu
/(d[əe]v[əe]t\s+olunmu[şs]\s+al[ıi]c[ıi]|hosted\s+buyer)\s+proqram[ıi]na\s+(qo[şs]ulun|d[əe]v[əe]t|se[çc]ildiniz)/iu

# ===== Russian =====
/(база|список)\s+(участников|посетителей|экспонентов|байеров|делегатов)\s+(выставки|форума|конференции|ярмарки)[^.]{0,50}(доступн[аы]|в\s+продаже|предлагаем)/iu
/(вас\s+)?(заинтересует|интересует)\s+(приобретение\s+)?(база|список)\s+(участников|посетителей|экспонентов)/iu
/программ[аеуы]\s+(приглаш[её]нных\s+покупателей|hosted\s+buyers?)/iu
/(оплата|сч[её]т)\s+(за\s+)?(стенд|площадь|спонсорство|участие)[^.]{0,30}(новые|изменились)\s+(банковские\s+)?реквизиты/iu
/(каталог|справочник)\s+(участников|экспонентов)[^.]{0,30}(обновите|подтвердите|проверьте)\s+(ваши\s+)?данные/iu

